import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Eye,
  EyeOff,
  ShieldCheck,
  CreditCard,
  RefreshCw,
  AlertCircle,
  CheckCircle2,
  User,
  Lock,
  ArrowRight,
  ArrowLeft,
  Building2,
  Sparkles,
  FileCheck,
  Info
} from 'lucide-react';

type Step = 1 | 2 | 3 | 4;

interface FormData {
  fullName: string;
  email: string;
  phone: string;
  aadhaarNumber: string;
  panNumber: string;
  annualIncome: string;
  occupation: string;
}

export default function KYCRegistrationForm() {
  const [currentStep, setCurrentStep] = useState<Step>(1);
  const [aadhaarVisible, setAadhaarVisible] = useState<boolean>(false);
  const [aadhaarError, setAadhaarError] = useState<string | null>(null);
  const [touchedAadhaar, setTouchedAadhaar] = useState<boolean>(false);

  // Credit Score Bureau State
  const [creditScore, setCreditScore] = useState<number>(768);
  const [isFetchingScore, setIsFetchingScore] = useState<boolean>(false);
  const [lastFetchedTimestamp, setLastFetchedTimestamp] = useState<string>('Just now');

  const [formData, setFormData] = useState<FormData>({
    fullName: 'Ananya Sharma',
    email: 'ananya.sharma@example.com',
    phone: '9876543210',
    aadhaarNumber: '',
    panNumber: 'ABCDE1234F',
    annualIncome: '₹12,000,000 - ₹25,000,000',
    occupation: 'Salaried Professional'
  });

  // Validate Aadhaar (Exact 12 digits regex)
  const validateAadhaar = (value: string): boolean => {
    const regex = /^\d{12}$/;
    if (!value) {
      setAadhaarError('Aadhaar number is required');
      return false;
    }
    if (!regex.test(value)) {
      setAadhaarError('Aadhaar must be exactly 12 numeric digits');
      return false;
    }
    setAadhaarError(null);
    return true;
  };

  const handleAadhaarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '').slice(0, 12);
    setFormData(prev => ({ ...prev, aadhaarNumber: rawValue }));
    if (touchedAadhaar) {
      validateAadhaar(rawValue);
    }
  };

  const handleAadhaarBlur = () => {
    setTouchedAadhaar(true);
    validateAadhaar(formData.aadhaarNumber);
  };

  const handleFetchCreditScore = () => {
    setIsFetchingScore(true);
    setTimeout(() => {
      // Generate realistic score between 650 and 820
      const newScore = Math.floor(Math.random() * (820 - 650 + 1)) + 650;
      setCreditScore(newScore);
      setLastFetchedTimestamp(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      setIsFetchingScore(false);
    }, 1200);
  };

  const formatAadhaarDisplay = (val: string) => {
    if (!val) return '';
    const cleaned = val.padEnd(12, '•');
    const part1 = cleaned.slice(0, 4);
    const part2 = cleaned.slice(4, 8);
    const part3 = cleaned.slice(8, 12);

    if (!aadhaarVisible) {
      return `•••• •••• ${val.slice(8, 12) || '••••'}`;
    }
    return `${part1} ${part2} ${part3}`;
  };

  const getCreditScoreCategory = (score: number) => {
    if (score >= 780) return { label: 'Exceptional', color: 'text-emerald-600', bg: 'bg-emerald-500', badgeBg: 'bg-emerald-100 text-emerald-800' };
    if (score >= 740) return { label: 'Very Good', color: 'text-emerald-500', bg: 'bg-emerald-400', badgeBg: 'bg-emerald-50 text-emerald-700' };
    if (score >= 670) return { label: 'Good', color: 'text-amber-500', bg: 'bg-amber-400', badgeBg: 'bg-amber-100 text-amber-800' };
    if (score >= 580) return { label: 'Fair', color: 'text-orange-500', bg: 'bg-orange-400', badgeBg: 'bg-orange-100 text-orange-800' };
    return { label: 'Poor', color: 'text-rose-600', bg: 'bg-rose-500', badgeBg: 'bg-rose-100 text-rose-800' };
  };

  const isStep1Valid = () => {
    return formData.fullName.trim() !== '' && /^\d{12}$/.test(formData.aadhaarNumber);
  };

  const handleNextStep = () => {
    if (currentStep === 1) {
      setTouchedAadhaar(true);
      if (!validateAadhaar(formData.aadhaarNumber)) return;
    }
    if (currentStep < 4) {
      setCurrentStep((prev) => (prev + 1) as Step);
    }
  };

  const handlePrevStep = () => {
    if (currentStep > 1) {
      setCurrentStep((prev) => (prev - 1) as Step);
    }
  };

  const scoreCategory = getCreditScoreCategory(creditScore);
  const scorePercentage = Math.min(Math.max(((creditScore - 300) / (850 - 300)) * 100, 0), 100);

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 flex items-center justify-center p-4 sm:p-6 font-sans">
      <div className="max-w-3xl w-full bg-slate-800/90 border border-slate-700/80 rounded-2xl shadow-2xl backdrop-blur-xl overflow-hidden">

        {/* Header Banner */}
        <div className="bg-gradient-to-r from-indigo-600 via-indigo-700 to-purple-700 p-6 sm:p-8 text-white relative overflow-hidden">
          <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-white/10 rounded-full blur-2xl pointer-events-none" />
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2.5 bg-white/10 rounded-xl backdrop-blur-md">
              <ShieldCheck className="w-6 h-6 text-indigo-200" />
            </div>
            <span className="text-xs font-semibold uppercase tracking-wider text-indigo-200 bg-white/10 px-3 py-1 rounded-full">
              Secure Verification Engine
            </span>
          </div>
          <h1 className="text-2xl sm:text-3xl font-bold tracking-tight">Customer KYC Registration</h1>
          <p className="text-indigo-100/80 text-sm mt-1">
            Verify identity with Aadhaar integration and credit risk bureau scoring
          </p>
        </div>

        {/* Stepper Progress Bar */}
        <div className="bg-slate-800 border-b border-slate-700/80 px-6 py-4">
          <div className="flex items-center justify-between max-w-xl mx-auto">
            {[
              { id: 1, label: 'Identity & Aadhaar' },
              { id: 2, label: 'Bureau Credit Check' },
              { id: 3, label: 'Review & Confirm' }
            ].map((s, idx) => (
              <React.Fragment key={s.id}>
                <div className="flex items-center gap-2.5">
                  <div
                    className={`w-9 h-9 rounded-full flex items-center justify-center font-semibold text-sm transition-all duration-300 ${' '}
                      ${currentStep === s.id
                        ? 'bg-indigo-600 text-white ring-4 ring-indigo-500/30 scale-105'
                        : currentStep > s.id
                        ? 'bg-emerald-500 text-white'
                        : 'bg-slate-700 text-slate-400'
                      }`}
                  >
                    {currentStep > s.id ? <CheckCircle2 className="w-5 h-5" /> : s.id}
                  </div>
                  <span className={`text-xs font-medium hidden sm:inline ${' '}
                    ${currentStep === s.id ? 'text-white font-semibold' : 'text-slate-400'}`}
                  >
                    {s.label}
                  </span>
                </div>
                {idx < 2 && (
                  <div className={`flex-1 h-0.5 mx-3 transition-colors duration-300 ${' '}
                    ${currentStep > idx + 1 ? 'bg-emerald-500' : 'bg-slate-700'}`}
                  />
                )}
              </React.Fragment>
            ))}
          </div>
        </div>

        {/* Main Content Area */}
        <div className="p-6 sm:p-8">
          <AnimatePresence mode="wait">
            {currentStep === 1 && (
              <motion.div
                key="step1"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                transition={{ duration: 0.25 }}
                className="space-y-6"
              >
                <div className="border-b border-slate-700/60 pb-3 mb-4">
                  <h2 className="text-lg font-semibold text-slate-100 flex items-center gap-2">
                    <User className="w-5 h-5 text-indigo-400" />
                    Personal & Identification Details
                  </h2>
                  <p className="text-xs text-slate-400 mt-0.5">
                    Provide legal identification for regulatory compliance verification.
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-slate-300 mb-1 rounded">
                      Full Legal Name
                    </label>
                    <input
                      type="text"
                      value={formData.fullName}
                      onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
                      className="w-full px-3.5 py-2.5 bg-slate-900/80 border border-slate-700 rounded-xl text-slate-100 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 text-sm transition-all"
                      placeholder="John Doe"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-slate-300 mb-1">
                      Email Address
                    </label>
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="w-full px-3.5 py-2.5 bg-slate-900/80 border border-slate-700 rounded-xl text-slate-100 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 text-sm transition-all"
                    />
                  </div>
                </div>

                {/* Aadhaar Input Field Area (Requirement 1, 2, 3) */}
                <div className="bg-slate-900/50 p-4 sm:p-5 rounded-2xl border border-indigo-500/20 relative">
                  <div className="flex items-center justify-between mb-2">
                    <label className="text-xs font-medium text-slate-200 flex items-center gap-1.5">
                      <Lock className="w-3.5 h-3.5 text-indigo-400" />
                      Aadhaar Number <span className="text-rose-400">*</span>
                    </label>
                    <span className="text-[11px] text-slate-400">12-Digit UIDAI Identifier</span>
                  </div>

                  <div className="relative">
                    <input
                      type={aadhaarVisible ? 'text' : 'password'}
                      maxLength={12}
                      value={formData.aadhaarNumber}
                      onChange={handleAadhaarChange}
                      onBlur={handleAadhaarBlur}
                      placeholder="Enter 12-digit Aadhaar number"
                      className={`w-full pl-4 pr-12 py-3 bg-slate-900 border rounded-xl font-mono text-base tracking-widest text-slate-100 transition-all focus:outline-none ${' '}
                        ${aadhaarError && touchedAadhaar
                          ? 'border-rose-500 focus:ring-1 focus:ring-rose-500/50 bg-rose-950/10'
                          : 'border-slate-700 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500'
                        }`}
                    />
                    <button
                      type="button"
                      onClick={() => setAadhaarVisible(!aadhaarVisible)}
                      className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-200 transition-colors p-1"
                      title={aadhaarVisible ? 'Mask Aadhaar Number' : 'Show Aadhaar Number'}
                    >
                      {aadhaarVisible ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>

                  {/* Real-time Validation Error Message (Requirement 3) */}
                  <AnimatePresence>
                    {aadhaarError && touchedAadhaar && (
                      <motion.div
                        initial={{ opacity: 0, y: -4 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -4 }}
                        className="flex items-center gap-1.5 text-rose-400 text-xs mt-2.5 font-medium"
                      >
                        <AlertCircle className="w-4 h-4 shrink-0" />
                        <span>{aadhaarError}</span>
                      </motion.div>
                    )}
                  </AnimatePresence>

                  <p className="text-[11px] text-slate-400 mt-2.5 flex items-center gap-1">
                    <Info className="w-3.5 h-3.5 text-slate-500 shrink-0" />
                    Valid format: Exactly 12 numeric digits (Regex enforced: <code className="text-indigo-300 font-mono">^\d&#123;12&#125;$</code>).
                  </p>
                </div>
              </motion.div>
            )}

            {currentStep === 2 && (
              <motion.div
                key="step2"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                transition={{ duration: 0.25 }}
                className="space-y-6"
              >
                <div className="border-b border-slate-700/60 pb-3 mb-4">
                  <h2 className="text-lg font-semibold text-slate-100 flex items-center gap-2">
                    <Building2 className="w-5 h-5 text-indigo-400" />
                    Bureau Financial & Credit Profile
                  </h2>
                  <p className="text-xs text-slate-400 mt-0.5">
                    Real-time score assessment retrieved from authorized Credit Bureau services.
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-slate-300 mb-1">
                      PAN Identifier
                    </label>
                    <input
                      type="text"
                      readOnly
                      value={formData.panNumber}
                      className="w-full px-3.5 py-2.5 bg-slate-900/50 border border-slate-700/80 rounded-xl text-slate-400 text-sm cursor-not-allowed font-mono uppercase"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-slate-300 mb-1">
                      Declared Annual Income
                    </label>
                    <input
                      type="text"
                      readOnly
                      value={formData.annualIncome}
                      className="w-full px-3.5 py-2.5 bg-slate-900/50 border border-slate-700/80 rounded-xl text-slate-400 text-sm cursor-not-allowed"
                    />
                  </div>
                </div>

                {/* Calculated Credit Score Display Element (Requirement 4) */}
                <div className="bg-slate-900/70 border border-slate-700/80 rounded-2xl p-5 sm:p-6 space-y-5 relative overflow-hidden">
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <div className="flex items-center gap-2">
                      <CreditCard className="w-5 h-5 text-indigo-400" />
                      <span className="text-sm font-semibold text-slate-200">
                        Calculated Credit Score
                      </span>
                      <span className="text-[10px] bg-indigo-950 border border-indigo-700/50 text-indigo-300 px-2 py-0.5 rounded-full uppercase tracking-wider font-semibold">
                        Bureau Verified
                      </span>
                    </div>

                    <button
                      type="button"
