                      className="flex items-center gap-1.5 text-xs text-indigo-400 hover:text-indigo-300 disabled:text-slate-500 transition-colors font-medium bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-700 hover:border-slate-600"
                    >
                      <RefreshCw className={`w-3.5 h-3.5 ${isFetchingScore ? 'animate-spin text-indigo-400' : ''}`} />
                      {isFetchingScore ? 'Re-querying Bureau...' : 'Refresh Bureau Score'}
