                  </div>

                  {/* Read-Only Bureau Meter Container */}
                  <div className="bg-slate-950/80 p-5 rounded-xl border border-slate-800 space-y-4">
                    <div className="flex items-baseline justify-between">
                      <div>
                        <div className="text-3xl font-extrabold text-white tracking-tight flex items-baseline gap-2">
                          {creditScore}
                          <span className="text-xs font-normal text-slate-400">/ 850 Max</span>
                        </div>
                        <div className="text-[11px] text-slate-400 mt-0.5">
                          Last synchronized: <span className="text-slate-300 font-mono">{lastFetchedTimestamp}</span>
                        </div>
                      </div>

                      <div className="text-right">
                        <span className={`inline-block text-xs font-bold px-3 py-1 rounded-full ${scoreCategory.badgeBg}`}>
                          {scoreCategory.label}
                        </span>
                      </div>
                    </div>

                    {/* Dynamic Risk Gauge / Meter Bar */}
                    <div className="space-y-1.5">
                      <div className="w-full h-3 bg-slate-800 rounded-full overflow-hidden p-0.5 border border-slate-700/60 relative">
