                </div>

                <div className="bg-slate-900/60 rounded-2xl border border-slate-700/80 p-5 space-y-4 divide-y divide-slate-800">
                  <div className="flex justify-between items-center pb-2">
                    <span className="text-xs text-slate-400">Customer Name</span>
                    <span className="text-sm font-medium text-slate-100">{formData.fullName}</span>
                  </div>
                  <div className="flex justify-between items-center pt-3 pb-2">
                    <span className="text-xs text-slate-400">Email Address</span>
                    <span className="text-sm font-medium text-slate-100">{formData.email}</span>
                  </div>
                  <div className="flex justify-between items-center pt-3 pb-2">
                    <span className="text-xs text-slate-400">Verified Aadhaar UID</span>
                    <span className="text-sm font-mono text-indigo-300 font-semibold">
                      {formatAadhaarDisplay(formData.aadhaarNumber)}
