                  </div>
                  <div className="flex justify-between items-center pt-3 pb-2">
                    <span className="text-xs text-slate-400">Calculated Credit Score</span>
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-bold text-slate-100">{creditScore}</span>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${scoreCategory.badgeBg}`}>
                        {scoreCategory.label}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="bg-indigo-950/40 border border-indigo-500/30 p-4 rounded-xl flex items-start gap-3">
                  <Sparkles className="w-5 h-5 text-indigo-400 shrink-0 mt-0.5" />
                  <p className="text-xs text-indigo-200/90 leading-relaxed">
                    By clicking <strong>Submit KYC Application</strong>, you certify that the 12-digit Aadhaar number and related financial details are accurate and authorized for regulatory compliance check.
                  </p>
                </div>
              </motion.div>
            )}

            {currentStep === 4 && (
              <motion.div
                key="step4"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.3 }}
                className="text-center py-8 space-y-4"
              >
                <div className="w-16 h-16 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded-full flex items-center justify-center mx-auto mb-2">
                  <CheckCircle2 className="w-10 h-10" />
                </div>
                <h2 className="text-2xl font-bold text-white">KYC Registration Completed</h2>
                <p className="text-slate-300 text-sm max-w-md mx-auto leading-relaxed">
                  Customer identification with Aadhaar UID <span className="text-indigo-300 font-mono">{formatAadhaarDisplay(formData.aadhaarNumber)}</span> and Bureau Credit Score rating of <span className="font-bold text-white">{creditScore}</span> has been processed successfully.
                </p>
                <div className="pt-4">
                  <button
                    type="button"
                    onClick={() => {
                      setCurrentStep(1);
                      setFormData(prev => ({ ...prev, aadhaarNumber: '' }));
                      setTouchedAadhaar(false);
                    }}
                    className="px-6 py-2.5 bg-slate-700 hover:bg-slate-600 text-white rounded-xl text-sm font-medium transition-all"
                  >
                    Register Another Customer
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Bottom Action Nav Controls */}
          {currentStep < 4 && (
            <div className="flex items-center justify-between mt-8 pt-4 border-t border-slate-700/60">
              <button
                type="button"
                onClick={handlePrevStep}
                disabled={currentStep === 1}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-medium transition-all ${' '}
                  ${currentStep === 1
                    ? 'opacity-0 pointer-events-none'
                    : 'text-slate-300 hover:text-white bg-slate-700/50 hover:bg-slate-700'
                  }`}
              >
                <ArrowLeft className="w-4 h-4" /> Back
              </button>

              {currentStep < 3 ? (
                <button
                  type="button"
                  onClick={handleNextStep}
                  disabled={currentStep === 1 && !isStep1Valid()}
                  className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl text-sm font-medium transition-all shadow-lg shadow-indigo-600/30"
                >
                  Continue <ArrowRight className="w-4 h-4" />
                </button>
              ) : (
                <button
                  type="button"
                  onClick={handleNextStep}
                  className="flex items-center gap-2 px-6 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-sm font-medium transition-all shadow-lg shadow-emerald-600/30"
                >
                  Submit KYC Application <CheckCircle2 className="w-4 h-4" />
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

